String _dailyWorkStatus(AdminProgressBatch batch) {
  final flow = batch.statusDetail.flowStatus.trim().toLowerCase();
  final wipStatus = batch.wipStatus.trim().toLowerCase();
  if (flow == 'consumed_by_next_stage' ||
      flow == 'accepted_to_stock' ||
      wipStatus == 'processed' ||
      wipStatus == 'used' ||
      wipStatus == 'consumed') {
    return 'Ishlatilgan';
  }
  if (flow == 'in_progress' ||
      wipStatus == 'in_use' ||
      wipStatus == 'in_progress' ||
      batch.statusDetail.workStatus.trim().toLowerCase() == 'paused') {
    return 'Jarayonda';
  }
  return 'Kutmoqda';
}

String _dailyWorkStatusLabel(
  BuildContext context,
  AdminProgressBatch batch,
) {
  return switch (_dailyWorkStatus(batch)) {
    'Ishlatilgan' => context.l10n.productionText('worker.daily.used'),
    'Jarayonda' => context.l10n.productionText(
        'worker.queue.status.in_progress',
      ),
    _ => context.l10n.productionText('worker.wip.waiting'),
  };
}

bool _canCorrectWip(AdminProgressBatch batch) =>
    batch.wipStatus.trim().toLowerCase() == 'waiting';

String _dailyWorkFirstNotEmpty(Iterable<String> values) {
  for (final value in values) {
    if (value.trim().isNotEmpty) {
      return value.trim();
    }
  }
  return '—';
}

String _dailyWorkApparatusLabel(
  Iterable<String> assignedApparatus,
  Iterable<AdminApparatus> catalog,
  AppLocalizations l10n,
) {
  final assignedIds = assignedApparatus.map((id) => id.trim()).toSet();
  final assigned = catalog
      .where((apparatus) => assignedIds.contains(apparatus.id.trim()))
      .toList(growable: false);
  if (assigned.any((apparatus) => apparatus.operation == 'print')) {
    return l10n.productionText('worker.daily.apparatus.print');
  }
  if (assigned.any((apparatus) => apparatus.operation == 'cut')) {
    return l10n.productionText('worker.daily.apparatus.cutting');
  }
  if (assigned.any((apparatus) => apparatus.operation == 'laminate')) {
    return l10n.productionText('worker.daily.apparatus.lamination');
  }
  for (final apparatus in assigned) {
    if (apparatus.name.trim().isNotEmpty) return apparatus.name.trim();
  }
  return l10n.productionText('worker.daily.apparatus.worker');
}

String _dailyWorkValue(String value) {
  final trimmed = value.trim();
  return trimmed.isEmpty ? '—' : trimmed;
}

String _dailyWorkDateLabel(DateTime value) {
  return '${value.day.toString().padLeft(2, '0')}. '
      '${value.month.toString().padLeft(2, '0')}. ${value.year}';
}

String _dailyWorkIdSuffix(String value) {
  final trimmed = value.trim().toLowerCase();
  if (trimmed.isEmpty) return '';
  final parts = trimmed.split(RegExp(r'[:/_-]+'));
  for (var i = parts.length - 1; i >= 0; i--) {
    if (parts[i].isNotEmpty) return parts[i];
  }
  return '';
}

/// Worker-facing WIP code: real QR/EPC payload first, never a raw
/// 80-char internal id. Falls back to a short tail of batchId.
String _dailyWorkDisplayCode(AdminProgressBatch batch) {
  final qr = batch.qrPayload.trim();
  if (qr.isNotEmpty) return qr;
  final id = batch.batchId.trim();
  if (id.isEmpty) return '—';
  if (id.length <= 24) return id;
  return '…${id.substring(id.length - 12)}';
}

String _dailyWorkQrOrDash(AdminProgressBatch batch) {
  final qr = batch.qrPayload.trim();
  if (qr.isNotEmpty) return qr;
  return _dailyWorkDisplayCode(batch);
}

/// Length in meters: finished-goods meter first, then produced qty when uom is m.
double? _dailyWorkLengthM(AdminProgressBatch batch) {
  if (batch.finishedGoodsMeter != null &&
      batch.finishedGoodsMeter!.isFinite &&
      batch.finishedGoodsMeter! > 0) {
    return batch.finishedGoodsMeter;
  }
  if (batch.uom.trim().toLowerCase() == 'm' &&
      batch.producedQty.isFinite &&
      batch.producedQty > 0) {
    return batch.producedQty;
  }
  return null;
}

/// Backend `label_item_name` has legacy form
/// `"<Mahsulot> yarim tayyor mahsulot, apparat: <raw-id>, <holat>"`.
/// Workers must never see the raw `apparatus:...` id — keep only product part.
String _dailyWorkProductTitle(AdminProgressBatch batch, [int index = 0]) {
  final candidates = <String>[
    batch.labelItemName.trim(),
    batch.labelItemCode.trim(),
  ];
  for (final raw in candidates) {
    if (raw.isEmpty) continue;
    var title = raw;
    final apparatIdx = title.toLowerCase().indexOf(', apparat:');
    if (apparatIdx > 0) {
      title = title.substring(0, apparatIdx).trim();
    } else {
      final bareIdx = title.toLowerCase().indexOf('apparat:');
      if (bareIdx > 0 && title.substring(0, bareIdx).trim().isNotEmpty) {
        title = title.substring(0, bareIdx).trim().replaceAll(
              RegExp(r'[,;:-]\s*$'),
              '',
            );
      }
    }
    if (title.isNotEmpty) return title;
  }
  return index > 0 ? 'WIP $index' : 'WIP';
}

String _dailyWorkReprintError(Object error, AppLocalizations l10n) {
